import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Tabela de Auto-verificação de Contradições de Configurações","description":"","frontmatter":{},"headers":[],"relativePath":"pt/0097-设定矛盾自查表.md","filePath":"pt/0097-设定矛盾自查表.md"}'),d={name:"pt/0097-设定矛盾自查表.md"};function s(r,e,n,c,u,m){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="tabela-de-auto-verificacao-de-contradicoes-de-configuracoes" tabindex="-1">Tabela de Auto-verificação de Contradições de Configurações <a class="header-anchor" href="#tabela-de-auto-verificacao-de-contradicoes-de-configuracoes" aria-label="Permalink to &quot;Tabela de Auto-verificação de Contradições de Configurações&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>97</td></tr><tr><td>Módulo</td><td>Apêndices e Materiais de Referência</td></tr><tr><td>Palavras-chave principais</td><td>auto-verificação de contradições, consistência de configurações, verificação lógica, controle de qualidade, manutenção de configurações</td></tr></tbody></table><h2 id="_1-descricao" tabindex="-1">1. Descrição <a class="header-anchor" href="#_1-descricao" aria-label="Permalink to &quot;1. Descrição&quot;">​</a></h2><p>A Tabela de Auto-verificação de Contradições de Configurações é uma ferramenta de controle de qualidade do sistema de configurações da Civilização de Simbiose de Âncora, usada para investigar sistematicamente possíveis contradições de configurações e inconsistências lógicas durante a criação de novas configurações, a revisão de configurações antigas e a atualização de documentos. Esta tabela de auto-verificação foi elaborada com base nas 14 configurações centrais e na lista de verificação de consistência estabelecidas no SPEC.md, cobrindo todos os módulos, como visão de mundo, sistema de cultivo, instituições sociais, sistema jurídico, formas de vida, sistema tecnológico, eras históricas e interação entre planos. Qualquer nova configuração ou conteúdo revisado deve passar por todos os itens de verificação desta tabela de auto-verificação antes de ser formalmente incorporado ao sistema de configurações.</p><h2 id="_2-verificacao-de-consistencia-das-configuracoes-centrais" tabindex="-1">2. Verificação de Consistência das Configurações Centrais <a class="header-anchor" href="#_2-verificacao-de-consistencia-das-configuracoes-centrais" aria-label="Permalink to &quot;2. Verificação de Consistência das Configurações Centrais&quot;">​</a></h2><h3 id="_2-1-nome-do-universo-e-conceitos-centrais" tabindex="-1">2.1 Nome do Universo e Conceitos Centrais <a class="header-anchor" href="#_2-1-nome-do-universo-e-conceitos-centrais" aria-label="Permalink to &quot;2.1 Nome do Universo e Conceitos Centrais&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item de verificação</th><th>Conteúdo da verificação</th><th>Critério de aprovação</th><th>Problema comum</th></tr></thead><tbody><tr><td>C01</td><td>Se o nome do universo está unificado</td><td>Usar uniformemente &quot;Wan Ling Heng Mao Ben Yuan Zhou&quot; ou a abreviação &quot;Hengyuanzhou&quot; em todo o texto, não usar outros nomes</td><td>Mistura de nomes não padronizados como &quot;universo&quot;, &quot;dez mil mundos&quot;, &quot;céus e mundos&quot;</td></tr><tr><td>C02</td><td>Se a definição de âncora está consistente</td><td>A âncora é sempre definida como &quot;nó estável na rede de leis&quot;, não alterar seus atributos essenciais</td><td>Descrever a âncora como objeto, ser vivo ou corpo de energia</td></tr><tr><td>C03</td><td>Se o conceito de simbiose está unificado</td><td>Simbiose sempre significa &quot;evolução comum por meio de cooperação mutuamente benéfica entre diferentes vidas&quot;, não desviar da posição anti-saque</td><td>Descrever simbiose assimilação, devoração ou controle</td></tr><tr><td>C04</td><td>Se a posição central está consistente</td><td>Sempre aderir ao princípio &quot;baseado na realidade&quot;, não descrever configurações fictícias como realidade</td><td>Confundir os limites entre ficção e realidade</td></tr></tbody></table><h3 id="_2-2-consistencia-do-sistema-de-cultivo" tabindex="-1">2.2 Consistência do Sistema de Cultivo <a class="header-anchor" href="#_2-2-consistencia-do-sistema-de-cultivo" aria-label="Permalink to &quot;2.2 Consistência do Sistema de Cultivo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item de verificação</th><th>Conteúdo da verificação</th><th>Critério de aprovação</th><th>Problema comum</th></tr></thead><tbody><tr><td>C05</td><td>Se o número total de sistemas está consistente</td><td>O número total de sistemas de cultivo de origem é sempre trezentos conjuntos, não aumentar ou diminuir</td><td>Aparição de expressões vagas como &quot;mais de trezentos conjuntos&quot;, &quot;centenas de conjuntos&quot;</td></tr><tr><td>C06</td><td>Se a classificação dos sistemas está consistente</td><td>Sempre dividir em seis categorias (dedução de origem, ciclo de vida, leis espaciais, elevação dimensional da consciência, rede de simbiose, engenharia aplicada), com cinquenta conjuntos em cada categoria</td><td>Aparição de outros métodos de classificação ou inconsistência no número de categorias</td></tr><tr><td>C07</td><td>Se as três bases de origem estão consistentes</td><td>Os três primeiros conjuntos são sempre iteração de dedução (001), ciclo de vida (002), gerenciamento de leis espaciais (003)</td><td>Alterar os números ou nomes dos três primeiros conjuntos</td></tr><tr><td>C08</td><td>Se a configuração da fruta Bei Zeng está consistente</td><td>A fruta Bei Zeng é sempre um &quot;buff inicial&quot;, fornece aumento de dedução de cem vezes, já foi aplicada tecnologicamente</td><td>Descrever a fruta Bei Zeng como fruta natural ou não tecnológica</td></tr><tr><td>C09</td><td>Se os reinos de cultivo estão consistentes</td><td>A divisão dos reinos de cada sistema está consistente com o documento 14 &quot;Divisão Unificada dos Reinos de Cultivo&quot;</td><td>Inventar nomes de reinos que contradizem a divisão unificada</td></tr><tr><td>C10</td><td>Se a posição anti-saque está consistente</td><td>Não descrever o cultivo de tipo saque como sistema positivo ou aceitável</td><td>Defender ou embelezar o cultivo de tipo saque</td></tr></tbody></table><h3 id="_2-3-consistencia-social-e-juridica" tabindex="-1">2.3 Consistência Social e Jurídica <a class="header-anchor" href="#_2-3-consistencia-social-e-juridica" aria-label="Permalink to &quot;2.3 Consistência Social e Jurídica&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item de verificação</th><th>Conteúdo da verificação</th><th>Critério de aprovação</th><th>Problema comum</th></tr></thead><tbody><tr><td>C11</td><td>Se a classificação da civilização está consistente</td><td>Sempre cinco tipos de classificação (intensivo da Ásia Oriental, bem-estar nórdico, plural da América do Norte, social da Europa continental, recuperação em desenvolvimento)</td><td>Aparição de um sexto tipo de classificação ou alteração dos nomes de classificação</td></tr><tr><td>C12</td><td>Se o sistema jurídico está consistente</td><td>Sempre constituição + lei do trabalho + lei de proteção ao consumidor + cinco leis complementares (educação, saúde, moradia, meio ambiente, antitruste)</td><td>Omitir alguma lei ou adicionar lei não configurada</td></tr><tr><td>C13</td><td>Se a estrutura de governança está consistente</td><td>Sempre Conselho de Âncora (legislativo) + Comitê Executivo de Simbiose (executivo) + Tribunal de Simbiose (judiciário) + Comitê de Supervisão de Âncora (supervisão)</td><td>Alterar os nomes das instituições ou a distribuição de poder</td></tr><tr><td>C14</td><td>Se o mecanismo de contrato de produção conjunta está consistente</td><td>Sempre centrado em &quot;mais trabalho mais ganho&quot;, alocação de recursos baseada em contribuição</td><td>Descrever o contrato de produção conjunta como igualitarismo ou alocação conforme necessidade</td></tr><tr><td>C15</td><td>Se a estratégia de ativação de 20% está consistente</td><td>Sempre ativar 20% de todos os seres como os mais fortes do plano na fase inicial</td><td>Alterar a proporção ou o objetivo de ativação</td></tr></tbody></table><h2 id="_3-verificacao-de-consistencia-logica-entre-modulos" tabindex="-1">3. Verificação de Consistência Lógica entre Módulos <a class="header-anchor" href="#_3-verificacao-de-consistencia-logica-entre-modulos" aria-label="Permalink to &quot;3. Verificação de Consistência Lógica entre Módulos&quot;">​</a></h2><h3 id="_3-1-consistencia-da-linha-do-tempo" tabindex="-1">3.1 Consistência da Linha do Tempo <a class="header-anchor" href="#_3-1-consistencia-da-linha-do-tempo" aria-label="Permalink to &quot;3.1 Consistência da Linha do Tempo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item de verificação</th><th>Conteúdo da verificação</th><th>Critério de aprovação</th><th>Problema comum</th></tr></thead><tbody><tr><td>L01</td><td>Se o tempo dos eventos históricos está consistente</td><td>O tempo de todos os eventos históricos está consistente com o documento 93 &quot;Resumo da Crônica&quot; e os documentos 70-79</td><td>O mesmo evento tem tempo inconsistente em diferentes documentos</td></tr><tr><td>L02</td><td>Se a divisão das eras está consistente</td><td>Os nomes das eras e os tempos de início e fim estão consistentes com o documento 70 &quot;Tabela Geral da Divisão das Eras&quot;</td><td>Aparição de era não configurada ou alteração dos limites das eras</td></tr><tr><td>L03</td><td>Se o período das pessoas está consistente</td><td>O período de atividade das pessoas-chave está consistente com o documento 95 &quot;Pessoas e Organizações-Chave&quot;</td><td>Pessoa aparece em uma época em que não existia</td></tr><tr><td>L04</td><td>Se o tempo de aparecimento da tecnologia está consistente</td><td>O tempo de invenção e maturação de cada tecnologia está consistente com a crônica</td><td>Alguma tecnologia é usada em uma época anterior à sua invenção</td></tr></tbody></table><h3 id="_3-2-consistencia-do-sistema-tecnologico" tabindex="-1">3.2 Consistência do Sistema Tecnológico <a class="header-anchor" href="#_3-2-consistencia-do-sistema-tecnologico" aria-label="Permalink to &quot;3.2 Consistência do Sistema Tecnológico&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item de verificação</th><th>Conteúdo da verificação</th><th>Critério de aprovação</th><th>Problema comum</th></tr></thead><tbody><tr><td>T01</td><td>Se a tecnologia do espelho de cópia está consistente</td><td>O espelho de cópia é sempre um &quot;dispositivo de cópia 1:1 que não toca o objeto original&quot;, processo de cópia com zero interferência</td><td>Descrever o espelho de cópia como capaz de alterar o objeto original ou precisar tocar o objeto original</td></tr><tr><td>T02</td><td>Se o espaço isolado está consistente</td><td>O espaço isolado é sempre um &quot;espaço independente completamente separado do exterior por uma barreira de leis&quot;</td><td>Descrever o espaço isolado como sala comum ou espaço virtual</td></tr><tr><td>T03</td><td>Se o requisito de cultivo de leis espaciais está consistente</td><td>O requisito de cultivo de cada tecnologia espacial está consistente com o documento 13 &quot;Detalhes do Sistema de Gerenciamento de Leis Espaciais&quot;</td><td>Pessoa de baixo cultivo usa tecnologia que requer alto cultivo</td></tr><tr><td>T04</td><td>Se a unidade de energia está consistente</td><td>A medição de energia usa uniformemente a &quot;unidade de energia padrão&quot;, não usar outras unidades</td><td>Mistura de unidades de energia não padronizadas como &quot;pedra espiritual&quot;, &quot;moeda de cristal&quot;</td></tr></tbody></table><h3 id="_3-3-consistencia-das-regras-entre-planos-e-temporais" tabindex="-1">3.3 Consistência das Regras entre Planos e Temporais <a class="header-anchor" href="#_3-3-consistencia-das-regras-entre-planos-e-temporais" aria-label="Permalink to &quot;3.3 Consistência das Regras entre Planos e Temporais&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item de verificação</th><th>Conteúdo da verificação</th><th>Critério de aprovação</th><th>Problema comum</th></tr></thead><tbody><tr><td>K01</td><td>Se &quot;primeiro observar, depois intervir limitadamente&quot; está consistente</td><td>Todas as operações de retrocesso temporal e entre planos devem seguir este princípio, não pular a fase de observação</td><td>Descrever operação de intervenção direta sem observação</td></tr><tr><td>K02</td><td>Se &quot;apenas transmitir conhecimento de volta&quot; está consistente</td><td>A produção arqueológica está limitada a conhecimento e informações abstratas, não transmitir matéria, energia ou seres vivos de volta</td><td>Descrever o ato de trazer relíquias arqueológicas ou amostras de volta ao próprio plano</td></tr><tr><td>K03</td><td>Se o sistema de permissão de viagem está consistente</td><td>Todas as viagens entre planos devem obter permissão do nível correspondente, não viajar sem permissão</td><td>Descrever viagem não autorizada por conta própria</td></tr><tr><td>K04</td><td>Se a classificação dos paradoxos temporais está consistente</td><td>Os paradoxos são sempre divididos em quatro categorias: avô, informação, ontologia, evento, não aumentar ou alterar</td><td>Aparição de tipo de paradoxo não configurado</td></tr><tr><td>K05</td><td>Se a classificação dos planos está consistente</td><td>Os planos são sempre divididos em cinco categorias (origem material, manifestação de energia, domínio da consciência, leis quebradas, vizinhança da origem)</td><td>Aparição de outros métodos de classificação</td></tr></tbody></table><h3 id="_3-4-consistencia-de-vida-e-racas" tabindex="-1">3.4 Consistência de Vida e Raças <a class="header-anchor" href="#_3-4-consistencia-de-vida-e-racas" aria-label="Permalink to &quot;3.4 Consistência de Vida e Raças&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item de verificação</th><th>Conteúdo da verificação</th><th>Critério de aprovação</th><th>Problema comum</th></tr></thead><tbody><tr><td>S01</td><td>Se a classificação das raças está consistente</td><td>As raças são sempre divididas em oito categorias (forma humana, forma animal, forma vegetal, forma elementar, forma de energia, forma de consciência, forma mecânica, forma mista)</td><td>Aparição de outros métodos de classificação</td></tr><tr><td>S02</td><td>Se o tratamento de vida estranha está consistente</td><td>A vida estranha é sempre tratada de acordo com três tipos de procedimentos padronizados de tratamento</td><td>Descrever tratamento arbitrário sem procedimento</td></tr><tr><td>S03</td><td>Se o tratamento do corpo de substituição das trevas está consistente</td><td>O corpo de substituição das trevas é sempre tratado de acordo com a ética da alma dupla e as regras de tratamento de quatro ramos</td><td>Descrever o ato de simplesmente eliminar uma das almas</td></tr><tr><td>S04</td><td>Se a igualdade de todas as raças está consistente</td><td>Todas as raças inteligentes são iguais perante a lei, não pode haver configuração de discriminação racial</td><td>Descrever alguma raça como inerentemente inferior ou destinada à escravidão</td></tr></tbody></table><h2 id="_4-verificacao-de-formato-e-normas-de-documentos" tabindex="-1">4. Verificação de Formato e Normas de Documentos <a class="header-anchor" href="#_4-verificacao-de-formato-e-normas-de-documentos" aria-label="Permalink to &quot;4. Verificação de Formato e Normas de Documentos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item de verificação</th><th>Conteúdo da verificação</th><th>Critério de aprovação</th><th>Problema comum</th></tr></thead><tbody><tr><td>F01</td><td>Se o formato do nome do arquivo está correto</td><td>O formato do nome do arquivo é &quot;XX-título do documento.md&quot;, XX é um número de dois dígitos</td><td>Número ausente, título com espaços, extensão de arquivo incorreta</td></tr><tr><td>F02</td><td>Se o bloco de informações do documento está completo</td><td>O início contém uma tabela de informações com número, módulo, palavras-chave principais (3-5)</td><td>Bloco de informações ausente ou campos incompletos</td></tr><tr><td>F03</td><td>Se o número de títulos de segundo nível atende ao padrão</td><td>O texto principal contém pelo menos 3 capítulos com títulos de segundo nível</td><td>Menos de 3 títulos de segundo nível</td></tr><tr><td>F04</td><td>Se elementos estruturados são usados</td><td>Usar elementos estruturados como listas e tabelas para melhorar a legibilidade</td><td>Apenas parágrafos de texto puro, sem listas ou tabelas</td></tr><tr><td>F05</td><td>Se a conclusão existe</td><td>Há um parágrafo de &quot;conclusão&quot; no final</td><td>Ausência de conclusão</td></tr><tr><td>F06</td><td>Se os documentos relacionados existem</td><td>Listar 2-3 números e nomes de documentos relacionados no final</td><td>Ausência de documentos relacionados ou documentos relacionados não existem</td></tr><tr><td>F07</td><td>Se a contagem de palavras atende ao padrão</td><td>O texto principal não é inferior a 800 palavras (excluindo título e metadados)</td><td>Texto principal inferior a 800 palavras</td></tr><tr><td>F08</td><td>Se o uso de terminologia está unificado</td><td>Usar terminologia padronizada como &quot;Hengyuanzhou&quot;, &quot;âncora&quot;, &quot;simbiose&quot;</td><td>Terminologia inconsistente ou uso de expressões não padronizadas</td></tr><tr><td>F09</td><td>Se o estilo de escrita é apropriado</td><td>Estilo de documento de configurações sério e sistemático, sem expressões coloquiais</td><td>Aparição de expressões coloquiais ou arbitrárias</td></tr><tr><td>F10</td><td>Se o número está consistente com a lista</td><td>O número e o título do documento estão consistentes com a lista completa de 100 documentos no SPEC.md</td><td>Número ou título não corresponde à lista</td></tr></tbody></table><h2 id="_5-processo-de-auto-verificacao-e-metodo-de-uso" tabindex="-1">5. Processo de Auto-verificação e Método de Uso <a class="header-anchor" href="#_5-processo-de-auto-verificacao-e-metodo-de-uso" aria-label="Permalink to &quot;5. Processo de Auto-verificação e Método de Uso&quot;">​</a></h2><h3 id="_5-1-processo-de-auto-verificacao-para-criacao-de-novas-configuracoes" tabindex="-1">5.1 Processo de Auto-verificação para Criação de Novas Configurações <a class="header-anchor" href="#_5-1-processo-de-auto-verificacao-para-criacao-de-novas-configuracoes" aria-label="Permalink to &quot;5.1 Processo de Auto-verificação para Criação de Novas Configurações&quot;">​</a></h3><ol><li><strong>Auto-verificação preliminar</strong>: Após a conclusão da criação, o criador verifica item por item com base nesta tabela de auto-verificação, marcando os itens com problemas.</li><li><strong>Revisão e aperfeiçoamento</strong>: Revisar os itens problemáticos marcados, garantindo que todos sejam aprovados.</li><li><strong>Auditoria cruzada</strong>: Submeter a outro criador de configurações para auditoria cruzada, com foco na verificação de consistência entre módulos.</li><li><strong>Aprovação do comitê</strong>: Alterações importantes de configurações devem ser submetidas à aprovação do Comitê de Manutenção de Configurações.</li><li><strong>Arquivamento e atualização</strong>: Após passar por todas as verificações, incorporar formalmente ao sistema de configurações e atualizar os documentos de índice relacionados.</li></ol><h3 id="_5-2-processo-de-auto-verificacao-para-revisao-de-configuracoes-antigas" tabindex="-1">5.2 Processo de Auto-verificação para Revisão de Configurações Antigas <a class="header-anchor" href="#_5-2-processo-de-auto-verificacao-para-revisao-de-configuracoes-antigas" aria-label="Permalink to &quot;5.2 Processo de Auto-verificação para Revisão de Configurações Antigas&quot;">​</a></h3><ol><li><strong>Avaliação de impacto</strong>: Avaliar outros documentos e módulos de configurações que podem ser afetados pelo conteúdo revisado.</li><li><strong>Verificação relacionada</strong>: Realizar verificação de consistência em todos os documentos relacionados afetados.</li><li><strong>Revisão síncrona</strong>: Realizar revisão síncrona do conteúdo afetado nos documentos relacionados.</li><li><strong>Registro de versão</strong>: Registrar o conteúdo revisado e o número da versão no documento 99 &quot;Versão e Instruções de Manutenção de Documentos&quot;.</li><li><strong>Anúncio e notificação</strong>: Revisões importantes devem publicar um anúncio de alteração para todos os usuários de configurações.</li></ol><h3 id="_5-3-auto-verificacao-abrangente-periodica" tabindex="-1">5.3 Auto-verificação Abrangente Periódica <a class="header-anchor" href="#_5-3-auto-verificacao-abrangente-periodica" aria-label="Permalink to &quot;5.3 Auto-verificação Abrangente Periódica&quot;">​</a></h3><p>O Comitê de Manutenção de Configurações realiza uma auto-verificação abrangente de consistência de configurações a cada trimestre, realizando uma verificação sistemática de todos os 100 documentos para investigar possíveis contradições de configurações e inconsistências lógicas. Os resultados da auto-verificação são formados no &quot;Relatório Trimestral de Consistência de Configurações&quot;, aberto a todos os usuários de configurações.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A Tabela de Auto-verificação de Contradições de Configurações é a &quot;constituição de qualidade&quot; do sistema de configurações da Civilização de Simbiose de Âncora. Por meio de itens de verificação sistemáticos e em forma de lista, ela garante que o sistema de configurações mantenha sempre a consistência lógica e a unidade de terminologia no processo de expansão e revisão contínuas. O que um grande sistema de configurações mais teme não é a falta de riqueza de conteúdo, mas o crescimento de contradições internas e a inconsistência entre o anterior e o posterior. A existência desta tabela de auto-verificação é para que o sistema de configurações da Civilização de Simbiose de Âncora, ao manter a abertura e a capacidade de crescimento, tenha sempre uma base sólida de consistência.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>99-Versão e Instruções de Manutenção de Documentos</li><li>90-Dicionário de Termos</li><li>00-Visão Geral do Universo de Hengyuanzhou</li></ul>',33)])])}const v=o(d,[["render",s]]);export{p as __pageData,v as default};
